SELECT
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  COUNT(*) AS ranged_cells,
  SUM(CAST(f.is_in_stock AS INT)) AS in_stock_cells,
  CAST(SUM(CAST(f.is_in_stock AS INT)) AS DOUBLE) / NULLIF(CAST(COUNT(*) AS DOUBLE), 0) AS stock_availability,
  SUM(CAST(f.closing_stock AS BIGINT)) AS closing_stock_units,
  SUM(CAST(f.sold_qty AS BIGINT)) AS stock_system_sold_units
FROM {{ ref('fact_inventory') }} AS f
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = f.retail_week_key
JOIN {{ ref('dim_store') }} AS st
  ON st.store_key = f.store_key
GROUP BY
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format
